static struct lock_class_key smc_inet_slock_key;
static struct lock_class_key smc_inet_lock_key;

static int smc_inet_init_sock(struct sock *sk)
{
	struct net *net = sock_net(sk);

	/* init common smc sock */
	smc_sk_init(net, sk, IPPROTO_SMC);

	/* The created sk is a SMC socket, but created via AF_INET(6).
	 * If we use the default AF_INET(6) lock keys, we might run into
	 * lockdep cycles with clcsock_release_lock and rtnl_mutex, because
	 * the clcsock is also an AF_INET(6) socket and uses the same keys.
	 *
	 * For example:
	 * rtnl_mutex -> sk_lock-AF_INET6 (generic dependency)
	 * sk_lock-AF_INET6 (smc) -> clcsock_release_lock
	 * clcsock_release_lock -> rtnl_mutex (closing clc sock)
	 *
	 * Break this by using a separate lock class for SMC-over-INET sockets.
	 */
	sock_lock_init_class_and_name(sk, "slock-AF_INET_SMC",
				      &smc_inet_slock_key,
				      "sk_lock-AF_INET_SMC",
				      &smc_inet_lock_key);

	inet_csk(sk)->icsk_sync_mss = smc_sync_mss;

	/* create clcsock */
	return smc_create_clcsk(net, sk, sk->sk_family);
}

